    const config = {
      max_discount_amount: {amount: 50, currency: 'usd'},
      discount_percent: 0,
    };
    const discountableLineItems: Array<DiscountableLineItem> = [
      {
        subtotal: {amount: 300, currency: 'usd'},
        quantity: 1,
        period: {
          type: 'time_range',
          start_date: new Date('2023-01-01T00:00:00Z'),
