  it('should not apply any discount when the currency is a mismatch', () => {
    const config = {
      max_discount_amount: {amount: 50, currency: 'cad'},
      discount_percent: 20,
    };
    const discountableLineItems: Array<DiscountableLineItem> = [
      {
