    });
  });

  it('should not apply any discount when the invoice amount is 0', () => {
    const config = {
      max_discount_amount: {amount: 50, currency: 'usd'},
      discount_percent: 20,
    };

    const discountableItem = {
      gross_amount: {amount: 0, currency: 'usd'},
